import { vec3 } from 'gl-matrix';
import { utilities as csUtils } from '@cornerstonejs/core';
import getViewportICamera from '../getViewportICamera.js';
import { navigatePlanarViewportToPoint } from '../genericViewportToolHelpers.js';
export default function translateViewportAlongNormal(viewport, distance) {
    if (!viewport || !Number.isFinite(distance) || distance === 0) {
        return false;
    }
    let camera;
    try {
        camera = getViewportICamera(viewport);
    }
    catch {
        return false;
    }
    const viewPlaneNormal = camera?.viewPlaneNormal;
    const focalPoint = camera?.focalPoint;
    const position = camera?.position;
    if (!viewPlaneNormal || !focalPoint || !position) {
        return false;
    }
    const newFocalPoint = vec3.scaleAndAdd(vec3.create(), focalPoint, viewPlaneNormal, distance);
    const newPosition = vec3.scaleAndAdd(vec3.create(), position, viewPlaneNormal, distance);
    if (csUtils.isGenericViewport(viewport)) {
        return navigatePlanarViewportToPoint(viewport, [
            newFocalPoint[0],
            newFocalPoint[1],
            newFocalPoint[2],
        ]);
    }
    viewport.setCamera({
        focalPoint: [newFocalPoint[0], newFocalPoint[1], newFocalPoint[2]],
        position: [newPosition[0], newPosition[1], newPosition[2]],
    });
    return true;
}
